SELECT count(*) FROM public.title title
  LEFT JOIN (SELECT key1, 1 AS hit FROM (SELECT cc.movie_id AS key1 FROM public.complete_cast cc, public.comp_cast_type cct1, public.comp_cast_type cct2 WHERE cct1.id = cc.subject_id AND cct2.id = cc.status_id AND cct1.kind = 'cast' AND cct2.kind = 'complete' INTERSECT SELECT mc.movie_id AS key1 FROM public.company_name cn, public.company_type ct, public.movie_companies mc WHERE ct.id = mc.company_type_id AND cn.id = mc.company_id AND cn.country_code != '[us]' INTERSECT SELECT mi.movie_id AS key1 FROM public.info_type it1, public.movie_info mi WHERE it1.id = mi.info_type_id AND it1.info = 'countries' AND (mi.info = 'Sweden' OR mi.info = 'Norway' OR mi.info = 'Germany' OR mi.info = 'Denmark' OR mi.info = 'Swedish' OR mi.info = 'Danish' OR mi.info = 'Norwegian' OR mi.info = 'German' OR mi.info = 'USA' OR mi.info = 'American') INTERSECT SELECT mi_idx.movie_id AS key1 FROM public.info_type it2, public.movie_info_idx mi_idx WHERE it2.id = mi_idx.info_type_id AND it2.info = 'rating' INTERSECT SELECT mk.movie_id AS key1 FROM public.keyword k, public.movie_keyword mk WHERE k.id = mk.keyword_id AND (k.keyword = 'murder' OR k.keyword = 'murder-in-title' OR k.keyword = 'blood' OR k.keyword = 'violence')) x) b1 ON title.id = b1.key1
  LEFT JOIN (SELECT DISTINCT key1, 1 AS hit FROM (SELECT kt.id AS key1 FROM public.kind_type kt WHERE (kt.kind = 'movie' OR kt.kind = 'episode')) x) b2 ON title.kind_id = b2.key1
WHERE (b2.hit IS NOT NULL AND b1.hit IS NOT NULL AND COALESCE(title.production_year > 2005, false));
